//! Verification for structure files, driven by the generic constant dump.
//!
//! # WHY THIS EXISTS
//!
//! `consts.txt` is generated by `_porting/java-oracle/ConstOracle.java`, which reflects over the
//! JAR's own class objects and emits one row per enum constant and per comparable `static final`
//! field. It currently covers **1,740 classes and 22,973 constants** -- every enum in the game.
//!
//! Before it, verifying an enum meant hand-writing a golden group for it, and that cost more
//! than the thing being checked. Now an enum port is one call to [`assert_enum`].
//!
//! # WHAT A VERIFIED ENUM ACTUALLY MEANS HERE
//!
//! The set of constant names matches the jar's exactly, and each one's `ordinal()` matches. That
//! is the whole risk surface of an enum: the names are the persisted strings, the ordinals are
//! the persisted integers, and a mismatch in either corrupts saved data without breaking a single
//! behavioural test. Field values (an enum's `id`, `index`, `serializedName`) are emitted too and
//! are checked by [`assert_enum_field`].
//!
//! # IT DOES NOT CHECK ANYTHING ELSE
//!
//! An enum with a hand-written `from_ordinal` that indexes the array wrongly still passes. That is
//! what Tier 1 is for; this file only claims what it checks, which is why a file verified here is
//! `VERIFIED` for its *constants* and the header says so.

use minecraft_rust::javacompat::golden::{Golden, Row};

fn const_rows(fq: &str) -> Vec<Row> {
    let g = Golden::load("consts.txt");
    let group = format!("const.{fq}");
    let rows = g.rows(&group);
    assert!(
        !rows.is_empty(),
        "consts.txt has no group `{group}`. Either the class is not an enum / has no comparable \
         static finals, or it is missing from the jar sweep. Check: \
         `Select-String -Path _porting/test-data/consts.txt -Pattern '#fn {group} '`"
    );
    rows.to_vec()
}

/// The `ordinal=<n>` entry out of a constant's expected column.
fn ordinal_of(row: &Row) -> i32 {
    for v in row.expect.iter() {
        let s = v.as_opt_str().unwrap_or("");
        if let Some(rest) = s.strip_prefix("ordinal=") {
            return rest.parse().expect("ordinal is a decimal int");
        }
    }
    panic!(
        "constant `{}` has no `ordinal=` entry; expected column was {:?}. An enum row without an \
         ordinal means the dump ran on something that is not an enum.",
        row.arg(0).as_opt_str().unwrap_or("?"),
        row.expect
    );
}

/// Look up one field entry, e.g. `id=clockwise_90`, out of a constant's expected column.
fn field_of(row: &Row, field: &str) -> String {
    for v in row.expect.iter() {
        let s = v.as_opt_str().unwrap_or("");
        if let Some(rest) = s.strip_prefix(&format!("{field}=")) {
            return rest.to_string();
        }
    }
    panic!(
        "constant `{}` has no `{field}=` entry; expected column was {:?}. The jar's enum does not \
         declare that public field, so the port must not invent one.",
        row.arg(0).as_opt_str().unwrap_or("?"),
        row.expect
    );
}

/// Assert an enum's constants match the jar's exactly: same set of names, same ordinals.
///
/// The name check is `assert_eq!` on **sorted lists**, not "every expected name is present". A
/// subset check would pass if the port invented an extra constant or dropped one, and both of
/// those are exactly what corrupts a save.
pub fn assert_enum(fq: &str, expected: &[(&str, i32)]) {
    let rows = const_rows(fq);
    let mut got: Vec<(String, i32)> = rows
        .iter()
        .map(|r| (r.arg(0).as_opt_str().unwrap_or("").to_string(), ordinal_of(r)))
        .collect();
    got.sort();
    let mut want: Vec<(String, i32)> = expected
        .iter()
        .map(|(n, o)| (n.to_string(), *o))
        .collect();
    want.sort();
    assert_eq!(
        got, want,
        "{fq}: constants do not match the jar.\n  jar has {} constants, the port declares {}.\n  \
         Compare against `_porting/test-data/consts.txt`, group `const.{fq}` -- the jar is ground \
         truth. A NAME difference is a persisted-string difference and an ORDINAL difference is a \
         persisted-int difference; both corrupt existing saves.",
        got.len(),
        want.len()
    );
}

/// Assert one enum constant's declared field value against the jar, e.g. `("Rotation",
/// "CLOCKWISE_180", "id", "str:180")`.
///
/// The expected form is the raw `type:value` string the dump writes, so there is no second
/// encoding to get wrong: what is asserted here is literally a substring of the golden row.
pub fn assert_enum_field(fq: &str, constant: &str, field: &str, expected: &str) {
    let rows = const_rows(fq);
    let row = rows
        .iter()
        .find(|r| r.arg(0).as_opt_str() == Some(constant))
        .unwrap_or_else(|| {
            panic!(
                "{fq} has no constant `{constant}` in the jar's dump. Known constants: {:?}",
                rows.iter()
                    .map(|r| r.arg(0).as_opt_str().unwrap_or("?"))
                    .collect::<Vec<_>>()
            )
        });
    assert_eq!(
        field_of(row, field),
        expected,
        "{fq}.{constant}.{field}: the jar says one thing and the port another. For `Rotation` \
         specifically: CLOCKWISE_180's id is \"180\", NOT \"clockwise_180\"."
    );
}

/// Assert a `static final` scalar against the jar, e.g. `("...ChunkPos", "REGION_SIZE",
/// "i32:32")`.
pub fn assert_const(fq: &str, field: &str, expected: &str) {
    let rows = const_rows(fq);
    let row = rows
        .iter()
        .find(|r| r.arg(0).as_opt_str() == Some(field))
        .unwrap_or_else(|| {
            panic!(
                "{fq} has no static final `{field}` in the jar's dump. The dump covers `static \
                 final` fields of primitive or String type only -- object-typed statics (Codecs, \
                 registries) are PORT-BLOCKED in the port instead, so a missing one here is \
                 expected rather than a failure."
            )
        });
    assert_eq!(
        field_of(row, "value"),
        expected,
        "{fq}.{field}: the jar says one thing and the port another."
    );
}

