#[test]
fn packet_flow_matches_the_jar() {
    // SERVERBOUND is ordinal 0, not 1 -- it is easy to assume the client-bound one leads.
    assert_enum(
        "net.minecraft.network.protocol.PacketFlow",
        &[("SERVERBOUND", 0), ("CLIENTBOUND", 1)],
    );
    assert_enum_field(
        "net.minecraft.network.protocol.PacketFlow",
        "SERVERBOUND",
        "id",
        "str:serverbound",
    );
    assert_enum_field(
        "net.minecraft.network.protocol.PacketFlow",
        "CLIENTBOUND",
        "id",
        "str:clientbound",
    );
}

#[test]
fn dialog_action_matches_the_jar() {
    assert_enum(
        "net.minecraft.server.dialog.DialogAction",
        &[("CLOSE", 0), ("NONE", 1), ("WAIT_FOR_RESPONSE", 2)],
    );
    // Both fields, on all three: `id` is the BY_ID key and `name` is the persisted spelling.
    for (c, id, name) in [
        ("CLOSE", 0, "close"),
        ("NONE", 1, "none"),
        ("WAIT_FOR_RESPONSE", 2, "wait_for_response"),
    ] {
        assert_enum_field("net.minecraft.server.dialog.DialogAction", c, "id", &format!("i32:{id}"));
        assert_enum_field(
            "net.minecraft.server.dialog.DialogAction",
            c,
            "name",
            &format!("str:{name}"),
        );
    }
}

#[test]
fn quart_pos_constants_match_the_jar() {
    for (f, v) in [("BITS", 2), ("SIZE", 4), ("MASK", 3)] {
        assert_const("net.minecraft.core.QuartPos", f, &format!("i32:{v}"));
    }
}

